/* GENERATED by scripts/build-atlas-data.cjs from atlas/graph/ — do not hand-edit. */
/* questions details for region "systems", loaded on demand by atlas/app.js (ATLAS.loadDetails). */
window.ATLAS.addDetails("systems.questions",{"questions":{
"q-water-cycle-0":{"target":{"node":"water-cycle","href":"../earth/climate/water-cycle/#step4"},"prompts":[{"node":"water-cycle","ask":{"zh":"海洋、空气、陆地三个水库之间，水通过蒸发、降水、径流流动，总量变了吗？","en":"Water flows between ocean, air and land through evaporation, rain and runoff — does the total amount change?"}},{"node":"feedback","ask":{"zh":"如果某处水变多了，流出会变快还是变慢？这种“多了就流走得更快”会让水量稳定下来吗？","en":"If one store holds more water, does its outflow speed up or slow down? Does \"more water flows out faster\" settle the amount at a steady value?"}}],"reveal":{"zh":"水只是在三个水库之间搬家，总量守恒；某处水多则流出加快、水少则流出减慢，于是各处水量收敛到稳定值。","en":"Water only moves between the three stores, so the total is conserved; a fuller store drains faster and an emptier one drains slower, so each store settles at a steady value."},"source":"../earth/climate/water-cycle/#step4","lesson":"water-cycle"},
"q-energy-pyramid-0":{"target":{"node":"energy-pyramid","href":"../biology/ecology/energy-pyramid/#step1"},"prompts":[{"node":"work-energy","ask":{"zh":"阳光固定的能量逐级传递时，每一级大约剩下多少？剩下的能量去哪了？","en":"As the Sun's fixed energy passes up the levels, roughly how much survives each step, and where does the rest go?"}},{"node":"energy-pyramid","ask":{"zh":"顶级捕食者处在第几级？按每级约剩一成算，它能分到的能量是生产者的几分之几？","en":"Which level do top predators sit at? At roughly a tenth surviving each step, what fraction of the producers' energy reaches them?"}},{"node":"feedback","ask":{"zh":"如果顶级捕食者变多了，对下级会产生什么连锁影响？这种反馈会让数量稳定还是失控？","en":"If top predators grew more numerous, what knock-on effect would that have down the levels? Would that feedback steady the numbers or run away?"}}],"reveal":{"zh":"每级约剩一成，顶级捕食者分到的能量只有生产者的千分之一左右，所以养得起的数量很少；数量变化会沿网传开又反推回来。","en":"About a tenth survives each level, so top predators get only around a thousandth of the producers' energy — very few can be supported, and changes ripple through the web and push back."},"source":"../biology/ecology/energy-pyramid/#step1","lesson":"energy-pyramid"},
"q-mechanical-energy-0":{"target":{"node":"mechanical-energy","href":"../physics/mechanics/mechanical-energy/#step1"},"prompts":[{"node":"mechanical-energy","ask":{"zh":"无摩擦时动能加势能守恒——过山车从高处冲下来，高度换成了什么？","en":"Without friction, kinetic plus potential energy is conserved — as the coaster dives from a height, what does the height turn into?"}},{"node":"work-energy","ask":{"zh":"冲上圆环顶端时，速度由高度差决定——为什么圆环的最低高度是 2.5R？","en":"Speed at the loop's top is set by the height difference — why must the start be at least 2.5R high?"}},{"node":"net-force","ask":{"zh":"在圆环顶端，重力和支持力的合力提供向心力——如果速度太小，合力不够会怎样？","en":"At the loop's top, gravity plus the track's push supply the centripetal force — if the speed is too small and the net force falls short, what happens?"}}],"reveal":{"zh":"高度换成速度，冲上圆环需要足够的动能；2.5R 保证顶端仍有速度、合力仍能提供向心力，车才不会掉下来。","en":"Height turns into speed, and climbing the loop needs enough kinetic energy; 2.5R guarantees speed remains at the top so the net force can still supply the centripetal force and the car stays on the track."},"source":"../physics/mechanics/mechanical-energy/#step1","lesson":"mechanical-energy"},
"q-activation-energy-0":{"target":{"node":"activation-energy","href":"../chemistry/reactions/activation-energy/#step2"},"prompts":[{"node":"probability","ask":{"zh":"只有能量超过能量山的分子才能反应——升温时，超过山顶的分子比例变大还是变小？","en":"Only molecules with energy above the hill can react — when temperature rises, does the share above the top grow or shrink?"}},{"node":"activation-energy","ask":{"zh":"k = A·e^(−Eₐ/RT) 里，T 变大时指数部分怎样变？为什么反应速率对温度这么敏感？","en":"In k = A·e^(−Eₐ/RT), what happens to the exponent as T grows? Why is the rate so sensitive to temperature?"}},{"node":"montecarlo","ask":{"zh":"如果用随机抽样模拟一群分子的能量，升温后能量分布的形状怎样变？","en":"If you simulate a crowd of molecules' energies by random sampling, how does the energy distribution's shape change on warming?"}}],"reveal":{"zh":"升温让超过活化能的分子比例指数式增加，所以速率随温度急剧上升；催化剂则是降低能量山本身。","en":"Warming raises the share of molecules above the activation energy exponentially, so the rate climbs steeply with temperature; a catalyst instead lowers the hill itself."},"source":"../chemistry/reactions/activation-energy/#step2","lesson":"activation-energy"},
"q-dna-replication-0":{"target":{"node":"dna-replication","href":"../biology/cells/dna-replication/#step3"},"prompts":[{"node":"probability","ask":{"zh":"碱基配对保证复制时新链和旧链互补——半保留复制是什么意思？子代 DNA 里旧链占几条？","en":"Base pairing makes each new strand complement the old — what does semi-conservative replication mean? How many old strands does each daughter DNA carry?"}},{"node":"dna-replication","ask":{"zh":"转录和翻译各把信息从什么变成什么？点突变改变的是碱基还是整个基因？","en":"Transcription and translation each convert information from what into what? Does a point mutation change a base or a whole gene?"}}],"reveal":{"zh":"DNA 半保留复制传下信息，转录成 RNA、翻译成蛋白质；点突变只改一个碱基，就可能改变一个氨基酸。","en":"DNA copies semi-conservatively to pass information on, transcribes it to RNA and translates it into protein; a point mutation changes a single base, which can change one amino acid."},"source":"../biology/cells/dna-replication/#step3","lesson":"dna-replication"},
"q-enzymes-0":{"target":{"node":"enzymes","href":"../biology/cells/enzymes/#step1"},"prompts":[{"node":"activation-energy","ask":{"zh":"酶降低活化能——底物浓度很低时，反应速率由什么限制？浓度高了呢？","en":"Enzymes lower the activation energy — at very low substrate concentration, what limits the rate? And at high concentration?"}},{"node":"enzymes","ask":{"zh":"米氏饱和曲线为什么会饱和？所有酶分子都被占满时，再加底物还有用吗？","en":"Why does the Michaelis–Menten curve level off? Once every enzyme is occupied, does adding more substrate help?"}},{"node":"feedback","ask":{"zh":"产物积累会反过来抑制酶吗？这种反馈对细胞有什么好处？","en":"Can accumulating product feed back to slow the enzyme? What good does that feedback do the cell?"}}],"reveal":{"zh":"酶分子数量有限，底物多了酶全被占满，速率就饱和了；产物反馈抑制还能自动调节快慢。","en":"Enzyme molecules are limited; with plenty of substrate they are all busy and the rate saturates; product feedback inhibition then regulates the pace automatically."},"source":"../biology/cells/enzymes/#step1","lesson":"enzymes"},
"q-gravity-orbits-0":{"target":{"node":"gravity-orbits","href":"../earth/astronomy/gravity-orbits/#step4"},"prompts":[{"node":"gravity-orbits","ask":{"zh":"横向发射速度决定轨道——速度低于圆速度、等于、高于时，轨道各是什么形状？","en":"Sideways launch speed decides the orbit — below, equal to, and above the circular speed, what shape is each orbit?"}},{"node":"net-force","ask":{"zh":"卫星一直受引力拉向地球，为什么不掉下来？合力在做什么？","en":"Gravity keeps pulling the satellite toward Earth, so why doesn't it fall? What is the net force doing?"}},{"node":"work-energy","ask":{"zh":"能量和角动量守恒给出近远点和等面积定律——卫星离地球近时速度快还是慢？","en":"Energy and angular momentum conservation give the near and far points and the equal-areas law — is the satellite faster near Earth or far from it?"}}],"reveal":{"zh":"卫星一直在掉，但横向速度让它掉的方向不断错开地面，绕着地球转；速度等于圆速度是圆轨道，达到 √2 倍就逃逸。","en":"The satellite is always falling, but its sideways speed keeps missing the ground, so it circles Earth; circular speed gives a circle, √2 times that escapes."},"source":"../earth/astronomy/gravity-orbits/#step4","lesson":"gravity-orbits"},
"q-pid-control-0":{"target":{"node":"pid-controller","href":"../engineering/control/pid-control/#step5"},"prompts":[{"node":"pid-controller","ask":{"zh":"只用 P 为什么常留下一点稳态误差？I 和 D 各补上了什么？","en":"Why does P alone usually leave a small steady-state error? What do I and D each add?"}},{"node":"feedback","ask":{"zh":"控制器每一步先问的问题是什么？误差从哪里来？","en":"What is the first question a controller asks at each step? Where does the error come from?"}}],"reveal":{"zh":"P 看现在差多少，差得越多推得越狠；I 记过去欠了多少，把残留误差慢慢吃掉；D 看误差变化得多快，提前刹车压住超调。三者的代价分别是冲过头、积分饱和和放大噪声。","en":"P looks at how far off it is now and pushes harder the farther it is; I keeps an account of past error and slowly eats the leftover; D watches how fast the error is changing and brakes early to limit overshoot. Their costs are overshoot, integral windup and amplified noise."},"source":"../engineering/control/pid-control/#step5","lesson":"pid-control"},
"q-step-response-0":{"target":{"node":"step-response","href":"../engineering/control/step-response/#step1"},"prompts":[{"node":"step-response","ask":{"zh":"阻尼比 ζ 小于 1、等于 1、大于 1 时，曲线各是什么形状？","en":"What does the curve look like for ζ below 1, equal to 1 and above 1?"}},{"node":"poles","ask":{"zh":"极点是一对复数还是两个负实数？它和摆不摆有什么关系？","en":"Are the poles a complex pair or two negative real numbers, and how does that relate to swinging?"}}],"reveal":{"zh":"阻尼不足（ζ < 1）时极点是一对复数，响应带着振荡冲过目标再收敛；ζ = 1 时刚好不冲过头；ζ > 1 时两个负实极点让输出只会慢慢爬。超调只由 ζ 决定，快慢由 ωn 决定。","en":"With too little damping (ζ < 1) the poles are a complex pair and the response overshoots with ringing before settling; at ζ = 1 it just avoids overshoot; with ζ > 1 two negative real poles make the output only creep. Overshoot depends on ζ alone, speed on ωn."},"source":"../engineering/control/step-response/#step1","lesson":"step-response"},
"q-attention-mechanism-0":{"target":{"node":"attention-mechanism","href":"../computing/ml/attention-mechanism/#step2"},"prompts":[{"node":"vectors","ask":{"zh":"查询与键的点积给出分数——点积大是什么意思？两个向量越像，分数越高还是越低？","en":"Query-key dot products give scores — what does a big dot product mean? The more alike two vectors are, the higher or lower the score?"}},{"node":"attention-mechanism","ask":{"zh":"softmax 把分数变成权重——权重加起来是多少？权重最大的词对输出影响最大吗？","en":"Softmax turns scores into weights — what do the weights add up to? Does the highest-weight word influence the output most?"}},{"node":"probability","ask":{"zh":"对值向量加权求和得到输出——权重为零的词对输出有贡献吗？","en":"A weighted sum of value vectors gives the output — does a zero-weight word contribute anything?"}}],"reveal":{"zh":"点积度量查询与键的相似，softmax 转成和为 1 的权重，输出就是值向量的加权平均——权重大的词主导了输出。","en":"The dot product measures query-key similarity, softmax turns it into weights summing to 1, and the output is the weighted average of value vectors — high-weight words dominate it."},"source":"../computing/ml/attention-mechanism/#step2","lesson":"attention-mechanism"},
"q-backpropagation-0":{"target":{"node":"backpropagation","href":"../computing/ml/backpropagation/#step2"},"prompts":[{"node":"derivative","ask":{"zh":"斜率在这里量的是什么？损失对某个权重的斜率告诉你什么？","en":"What does a slope measure here? What does the slope of the loss with respect to one weight tell you?"}},{"node":"backpropagation","ask":{"zh":"链式法则怎样把输出端的责任一路乘回每个权重？为什么一次向后扫描就够了？","en":"How does the chain rule multiply the output's blame all the way back to every weight? Why is one backward sweep enough?"}},{"node":"gradient-descent","ask":{"zh":"梯度到手后，权重往哪个方向走一小步？步子太大或太小会怎样？","en":"Once you have the gradient, which way does each weight take a small step? What goes wrong if the step is too big or too small?"}}],"reveal":{"zh":"链式法则把损失的责任从输出一路往回乘到每个权重，一次向后扫描就得到全部梯度，不用逐个权重扰动试错。梯度到手后，权重沿着使损失减小的方向走一小步，这就是梯度下降。","en":"The chain rule multiplies the loss's blame backwards from the output to every weight, so one backward sweep yields all gradients instead of perturbing each weight one by one. With gradients in hand, each weight takes a small step in the direction that reduces the loss — that is gradient descent."},"source":"../computing/ml/backpropagation/#step2","lesson":"backpropagation"},
"q-chaos-threebody-0":{"target":{"node":"chaos-threebody","href":"../physics/mechanics/chaos-threebody/#step3"},"prompts":[{"node":"chaos-threebody","ask":{"zh":"确定的规则也能产生无法长期预测的行为——初始误差按 e^{λt} 放大，λ > 0 意味着什么？","en":"Deterministic rules can still be unpredictable long term — initial errors grow like e^{λt}; what does λ > 0 mean?"}},{"node":"feedback","ask":{"zh":"可预测期限只与精度的对数成正比——观测精度提高 10 倍，预报期限延长几倍还是只延长一点？","en":"The predictable horizon grows only with the logarithm of precision — improve observations tenfold, and does the horizon stretch several times or just a little?"}}],"reveal":{"zh":"误差指数放大，精度提高 10 倍也只把可预测期限延长一个常数；洛伦兹吸引子与三体 8 字轨道都是确定规则、长期不可预测的例子。","en":"Errors grow exponentially, so tenfold better precision only extends the horizon by a constant; the Lorenz attractor and the three-body figure-eight are deterministic yet unpredictable long term."},"source":"../physics/mechanics/chaos-threebody/#step3","lesson":"chaos-threebody"},
"q-ode-phase-portraits-0":{"target":{"node":"ode-phase-portraits","href":"../math/calculus/ode-phase-portraits/#step2"},"prompts":[{"node":"derivative","ask":{"zh":"时间曲线和相平面看的是同一件事吗？相平面上横轴纵轴各是什么？","en":"Do time curves and the phase plane show the same thing? What are the phase plane's axes?"}},{"node":"ode-phase-portraits","ask":{"zh":"零线与平衡点怎样找？平衡点附近，种群是回到平衡还是绕圈？","en":"How do you find nullclines and the equilibrium? Near equilibrium, do the populations return to it or circle around?"}},{"node":"eigen","ask":{"zh":"守恒量 H 不变意味着轨线是什么形状？加拥挤项后闭圈为什么变成螺旋？","en":"A conserved quantity H means what shape for the trajectories? Why does adding a crowding term turn closed loops into spirals?"}}],"reveal":{"zh":"相平面上轨线绕平衡点转圈，对应两个种群此起彼伏；守恒量 H 定出闭圈，加拥挤项耗散能量，闭圈收成螺旋。","en":"Trajectories circle the equilibrium in the phase plane, matching two populations rising and falling in turn; the conserved H fixes closed loops, and a crowding term dissipates energy, winding loops into spirals."},"source":"../math/calculus/ode-phase-portraits/#step2","lesson":"ode-phase-portraits"},
"q-prisoners-dilemma-0":{"target":{"node":"prisoners-dilemma","href":"../math/applied/prisoners-dilemma/#step3"},"prompts":[{"node":"game-theory","ask":{"zh":"一次博弈里背叛为什么占优？占优策略需要知道对手会怎么做吗？","en":"Why does defection dominate a single round? Does a dominant strategy need to know what the opponent will do?"}},{"node":"prisoners-dilemma","ask":{"zh":"重复博弈和继续概率阈值 δ* 怎样改变结论？噪声下宽容为什么有价值？","en":"How do repeated play and the continuation threshold δ* change the conclusion? Why is forgiveness valuable under noise?"}},{"node":"natural-selection","ask":{"zh":"得分怎样决定谁被复制？三策略复制者动态里，合作者靠什么翻盘？","en":"How does score decide who gets copied? In three-strategy replicator dynamics, what lets cooperators turn the tables?"}}],"reveal":{"zh":"一次博弈中背叛占优，但重复博弈、循环赛与继续概率阈值 δ* 让合作有了未来收益。三策略复制者动态里，得分决定谁被复制，噪声下宽容的策略反而活得更久。","en":"Defection dominates a single round, but repeated play, round-robins and the continuation threshold δ* give cooperation future payoffs. In three-strategy replicator dynamics score decides who is copied, and forgiving strategies last longer under noise."},"source":"../math/applied/prisoners-dilemma/#step3","lesson":"prisoners-dilemma"},
"q-recursion-divide-0":{"target":{"node":"recursion-divide","href":"../computing/algorithms/recursion-divide/#step2"},"prompts":[{"node":"recursion-divide","ask":{"zh":"规模怎样缩小、每层做多少事，怎样共同决定总代价？归并排序的分而治之长什么样？","en":"How do shrinking size and per-level work together set the total cost? What does merge sort's divide-and-conquer look like?"}},{"node":"binary-search","ask":{"zh":"每次对半砍时，规模缩小得有多快？为什么有序是前提？","en":"When you halve the range each time, how fast does the size shrink? Why is sorted order a precondition?"}},{"node":"exp-log","ask":{"zh":"汉诺塔的步数为什么按指数长？对数和“砍几次”有什么关系？","en":"Why does the Tower of Hanoi's step count grow exponentially? What does a logarithm have to do with “how many halvings”?"}}],"reveal":{"zh":"递归的总代价由规模缩小速度和每层工作量共同决定：二分查找每次对半砍、步数按对数长，所以瞬间完成。汉诺塔每层翻倍、步数按指数长，规模稍大就永远算不完。","en":"A recursion's total cost is set by how fast the size shrinks and how much each level does: binary search halves each time so its steps grow logarithmically and it finishes instantly. The Tower of Hanoi doubles each level so its steps grow exponentially, and a slightly bigger size never finishes."},"source":"../computing/algorithms/recursion-divide/#step2","lesson":"recursion-divide"},
"q-shortest-path-0":{"target":{"node":"shortest-path","href":"../computing/algorithms/shortest-path/#step1"},"prompts":[{"node":"graph-algorithms","ask":{"zh":"图上的算法一般先定义什么（点、边、代价）？为什么“按顺序展开”是个通用想法？","en":"What does a graph algorithm usually define first (vertices, edges, costs)? Why is “expanding in order” a general idea?"}},{"node":"shortest-path","ask":{"zh":"迪杰斯特拉每次确认暂定距离最小的点，为什么这样能保证最短？负权为什么会让它出错？","en":"Why does settling the smallest tentative distance each time guarantee the shortest path? Why do negative weights break it?"}},{"node":"pagerank","ask":{"zh":"同样在图上累积一个量，PageRank 和最短路累积的东西有什么不同？","en":"PageRank also accumulates a quantity over a graph — how does what it accumulates differ from a shortest path?"}}],"reveal":{"zh":"带权图里路径代价是权重之和，迪杰斯特拉每次确认暂定距离最小的点、像洪水从起点漫开。负权会让它出错，网格地图上泥地代价决定穿过还是绕开，A* 用启发值少确认一些格。","en":"In a weighted graph a path's cost is the sum of weights, and Dijkstra settles the smallest tentative distance each time, like a flood from the start. Negative weights make it fail, mud costs on a grid decide crossing versus detouring, and A* uses a heuristic to settle fewer cells."},"source":"../computing/algorithms/shortest-path/#step1","lesson":"shortest-path"}
}});
